def sector(p,cx,cy,r1,r2,a,b,fill):
 pts=[polar(cx,cy,r2,a+(b-a)*i/90) for i in range(91)]
 pts+=[polar(cx,cy,r1,b-(b-a)*i/90) for i in range(91)]
 path(p,pts,EDGE,.5,fill)
